com.mirth.connect.plugins.javascriptstep.script:
var messageCode = msg['MSH']['MSH.9']['MSH.9.1'].toString();
var triggerEvent = msg['MSH']['MSH.9']['MSH.9.2'].toString();
var controlId = msg['MSH']['MSH.10']['MSH.10.1'].toString();

var appointmentId =
    msg['SCH']['SCH.1']['SCH.1.1'].toString();

var patientId =
    msg['PID']['PID.3']['PID.3.1'].toString();

if (messageCode !== 'SIU') {
    throw new Error(
        'Unsupported message type: expected SIU but received ' +
        messageCode
    );
}

if (triggerEvent !== 'S12' && triggerEvent !== 'S15') {
    throw new Error(
        'Unsupported SIU trigger event: ' + triggerEvent
    );
}

if (!controlId) {
    throw new Error('Missing mandatory field MSH-10');
}

if (!appointmentId) {
    throw new Error('Missing mandatory field SCH-1');
}

if (!patientId) {
    throw new Error('Missing mandatory field PID-3.1');
}

//console.log("print.MessagewCode = " + messageCode); 
//console.log("print.eventCode = " + eventCode); 
//console.log("print.controlId = " + controlId); 
//console.log("demo"); 

channelMap.put('messageCode', messageCode);
channelMap.put('eventCode', triggerEvent);
channelMap.put('controlId', controlId);

com.mirth.connect.plugins.javascriptrule.script:
var rawEventCode = $('eventCode');
var eventCode = String(rawEventCode).trim();

logger.info(
    'S12.eventCode=[' + eventCode +
    '] typeof before=[' + typeof rawEventCode +
    '] typeof after=[' + typeof eventCode + ']'
);

return eventCode === 'S12';

var rawEventCode = $('eventCode');
var eventCode = String(rawEventCode).trim();

logger.info(
    'S15.eventCode=[' + eventCode +
    '] typeof before=[' + typeof rawEventCode +
    '] typeof after=[' + typeof eventCode + ']'
);

return eventCode === 'S15';

channel.postprocessingScript:
// This script executes once after a message has been processed
// Responses returned from here will be stored as "Postprocessor" in the response map
return;

channel.deployScript:
// This script executes once when the channel is deployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;

channel.undeployScript:
// This script executes once when the channel is undeployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;
